import { defineTable, type Timestamp } from "@intellectual-frontiers/data/sql/typed";

/** A source system's value mapped to the canonical value, with how the two relate, the rule it follows, who approved it and the dates between which it holds */
export interface MappingRow {
  /** What identifies the mapping */
  readonly mappingId: string;
  /** The system the value is from */
  readonly sourceSystem: string;
  /** The field the value is of */
  readonly sourceField: string;
  /** The value as the source gives it */
  readonly sourceValue: string;
  /** The canonical field */
  readonly targetField: string;
  /** The canonical value; none where the relationship is unmapped */
  readonly targetValue: string | null;
  /** How the two relate */
  readonly relationshipType: "equivalent" | "broader" | "narrower" | "related" | "unmapped";
  /** The rule it follows, where it is more than a lookup */
  readonly rule: string | null;
  /** Where it is in its approval */
  readonly status: "draft" | "approved" | "retired";
  /** Who approved it */
  readonly approvedBy: string | null;
  /** When it was approved */
  readonly approvedAt: Timestamp | null;
  /** From when it holds */
  readonly validFrom: Timestamp;
  /** Until when it holds, where it ends */
  readonly validTo: Timestamp | null;
}

/** What an insert into mapping takes: what the database fills may be left out. */
export interface MappingInsert {
  readonly mappingId: string;
  readonly sourceSystem: string;
  readonly sourceField: string;
  readonly sourceValue: string;
  readonly targetField: string;
  readonly targetValue?: string | null;
  readonly relationshipType: "equivalent" | "broader" | "narrower" | "related" | "unmapped";
  readonly rule?: string | null;
  readonly status: "draft" | "approved" | "retired";
  readonly approvedBy?: string | null;
  readonly approvedAt?: Timestamp | null;
  readonly validFrom: Timestamp;
  readonly validTo?: Timestamp | null;
}

/** The key of a row of mapping. */
export type MappingKey = { readonly mappingId: string };

/** A source system's value mapped to the canonical value, with how the two relate, the rule it follows, who approved it and the dates between which it holds */
export const mapping = defineTable<MappingRow, MappingInsert, "mapping">({
  alias: "mapping",
  name: "mapping",
  columns: {
    mappingId: "mapping_id",
    sourceSystem: "source_system",
    sourceField: "source_field",
    sourceValue: "source_value",
    targetField: "target_field",
    targetValue: "target_value",
    relationshipType: "relationship_type",
    rule: "rule",
    status: "status",
    approvedBy: "approved_by",
    approvedAt: "approved_at",
    validFrom: "valid_from",
    validTo: "valid_to",
  },
  primaryKey: ["mappingId"],
});

/** A known difference between a source and the canonical form, with who decided to live with it and when that ends: a variance is accepted for a time and then expires */
export interface VarianceRow {
  /** What identifies the variance */
  readonly varianceId: string;
  /** The source and field it is about */
  readonly subject: string;
  /** What differs, in a sentence */
  readonly description: string;
  /** Where it is */
  readonly status: "open" | "accepted" | "resolved" | "expired";
  /** Who answers for it */
  readonly owner: string;
  /** Who decided to accept it */
  readonly decidedBy: string | null;
  /** When it was decided */
  readonly decidedAt: Timestamp | null;
  /** When the acceptance ends */
  readonly expiresAt: Timestamp | null;
}

/** What an insert into variance takes: what the database fills may be left out. */
export interface VarianceInsert {
  readonly varianceId: string;
  readonly subject: string;
  readonly description: string;
  readonly status: "open" | "accepted" | "resolved" | "expired";
  readonly owner: string;
  readonly decidedBy?: string | null;
  readonly decidedAt?: Timestamp | null;
  readonly expiresAt?: Timestamp | null;
}

/** The key of a row of variance. */
export type VarianceKey = { readonly varianceId: string };

/** A known difference between a source and the canonical form, with who decided to live with it and when that ends: a variance is accepted for a time and then expires */
export const variance = defineTable<VarianceRow, VarianceInsert, "variance">({
  alias: "variance",
  name: "variance",
  columns: {
    varianceId: "variance_id",
    subject: "subject",
    description: "description",
    status: "status",
    owner: "owner",
    decidedBy: "decided_by",
    decidedAt: "decided_at",
    expiresAt: "expires_at",
  },
  primaryKey: ["varianceId"],
});

/** What a missing value is allowed to be for one field, the kind of absence it stands for and the default where it is replaced: the null policy of a field */
export interface NullRuleRow {
  /** What identifies the rule: its table and column */
  readonly nullRuleId: string;
  /** The table and column it is about */
  readonly subject: string;
  /** What is done with a missing value */
  readonly policy: "reject" | "allow_absent" | "default_to";
  /** The kind of absence a missing value is taken to be */
  readonly absence: "not_collected" | "not_applicable" | "unknown" | "not_yet_known" | "refused" | "suppressed" | "invalid" | null;
  /** The default, where the policy is to replace */
  readonly defaultValue: string | null;
  /** Why */
  readonly rationale: string;
}

/** What an insert into null_rule takes: what the database fills may be left out. */
export interface NullRuleInsert {
  readonly nullRuleId: string;
  readonly subject: string;
  readonly policy: "reject" | "allow_absent" | "default_to";
  readonly absence?: "not_collected" | "not_applicable" | "unknown" | "not_yet_known" | "refused" | "suppressed" | "invalid" | null;
  readonly defaultValue?: string | null;
  readonly rationale: string;
}

/** The key of a row of null_rule. */
export type NullRuleKey = { readonly nullRuleId: string };

/** What a missing value is allowed to be for one field, the kind of absence it stands for and the default where it is replaced: the null policy of a field */
export const nullRule = defineTable<NullRuleRow, NullRuleInsert, "nullRule">({
  alias: "nullRule",
  name: "null_rule",
  columns: {
    nullRuleId: "null_rule_id",
    subject: "subject",
    policy: "policy",
    absence: "absence",
    defaultValue: "default_value",
    rationale: "rationale",
  },
  primaryKey: ["nullRuleId"],
});
